config.transformVars:
const toUtc = (s) => { const [y, m, d] = s.split('-').map(Number); return Date.UTC(y, m - 1, d); };
const dayMs = 24 * 60 * 60 * 1000;
const start = toUtc(vars.policy_start_date);
const treat = toUtc(vars.treatment_date);
const sub = toUtc(vars.submission_date);
const [ty, tm, td] = vars.treatment_date.split('-').map(Number);
const deadline = (tm === 2 && td === 29) ? Date.UTC(ty + 1, 1, 28) : Date.UTC(ty + 1, tm - 1, td);
let onTime;
if (sub < treat) onTime = 'invalid (submission date is before treatment date)';
else onTime = sub <= deadline ? 'yes' : 'no';
return {
  ...vars,
  days_since_policy_start: Math.round((treat - start) / dayMs),
  days_since_treatment: Math.round((sub - treat) / dayMs),
  submitted_on_time: onTime,
};

